import './friends.scss';
import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import { Link } from 'react-router-dom';

const Friends = () => {
  const { currentUser, token, loading: authLoading, error: authError } = useContext(AuthContext);
  const [friends, setFriends] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  console.log('Friends: currentUser=', currentUser);
  console.log('Friends: token=', token);
  console.log('Friends: authLoading=', authLoading);
  console.log('Friends: authError=', authError);

  useEffect(() => {
    const fetchFriends = async () => {
      if (authLoading) {
        console.log('Friends: Waiting for AuthContext to load');
        return;
      }

      if (!currentUser || !token) {
        console.log('Friends: No currentUser or token, cannot fetch friends');
        setError('Please log in to view your friends.');
        setLoading(false);
        return;
      }

      try {
        console.log('Friends: Sending GET request to http://localhost:5000/api/users/me');
        const res = await axios.get('http://localhost:5000/api/users/me', {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('Friends: Fetch user response=', {
          status: res.status,
          data: JSON.stringify(res.data, null, 2),
        });
        if (!res.data || !res.data.friends) {
          console.log('Friends: No valid user or friends data returned');
          setError('No friends data found.');
          setFriends([]);
        } else {
          console.log('Friends: Setting friends=', res.data.friends);
          setFriends(res.data.friends);
          setError(null);
        }
      } catch (err) {
        console.error('Friends: Error fetching friends:', err.message);
        console.error('Friends: Error details:', {
          status: err.response?.status,
          data: JSON.stringify(err.response?.data, null, 2),
        });
        const errorMessage = err.response?.status === 401
          ? 'Session expired. Please log in again.'
          : err.response?.data?.message || 'Failed to load friends.';
        setError(errorMessage);
        setFriends([]);
      } finally {
        setLoading(false);
        console.log('Friends: fetchFriends completed, loading=', false);
      }
    };

    fetchFriends();
  }, [currentUser, token, authLoading]);

  if (authLoading || loading) {
    return <div className="friends">Loading friends...</div>;
  }

  if (error) {
    return (
      <div className="friends error">
        <p>{error}</p>
        <button onClick={() => window.location.reload()}>Retry</button>
      </div>
    );
  }

  return (
    <div className="friends">
      <h2>Your Friends</h2>
      {friends.length === 0 ? (
        <p>You have no friends yet. Go to <Link to="/add-friends">Add Friends</Link> to connect!</p>
      ) : (
        <div className="friends-list">
          {friends.map((friend) => (
            <div key={friend._id} className="friend-card">
              <Link to={`/profile/${friend._id}`}>
                <img
                  src={friend.profilePicture || '/default-avatar.png'}
                  alt={`${friend.username}'s profile`}
                  className="avatar"
                  onError={(e) => {
                    console.error(`Friends: Image load error for ${friend.username}:`, e);
                    e.target.src = '/default-avatar.png';
                  }}
                />
                <div className="info">
                  <h3>{friend.username}</h3>
                  <p>{friend.name}</p>
                </div>
              </Link>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Friends;
